import{_ as a,o as e,c as o,ai as r}from"./chunks/framework.ampVZV4B.js";const y=JSON.parse('{"title":"Python · 02 核心能力","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/python/02-core.md","filePath":"tech-system/backend/python/02-core.md"}'),d={name:"tech-system/backend/python/02-core.md"};function n(h,t,i,l,s,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="python-·-02-核心能力" tabindex="-1">Python · 02 核心能力 <a class="header-anchor" href="#python-·-02-核心能力" aria-label="Permalink to “Python · 02 核心能力”">​</a></h1><blockquote><p>真正不同的地方：动态类型代价、GIL、asyncio、性能与适合边界。</p></blockquote><h2 id="_1-动态类型-效率与风险" tabindex="-1">1. 动态类型：效率与风险 <a class="header-anchor" href="#_1-动态类型-效率与风险" aria-label="Permalink to “1. 动态类型：效率与风险”">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>好处</td><td>改得快、脚本多、原型一天能出</td></tr><tr><td>风险</td><td>重构胆怯、线上类型相关 Bug 更隐蔽、IDE/审查更难</td></tr></tbody></table><p><strong>我的做法：</strong></p><ul><li>对外：FastAPI + Pydantic（入参出参强制结构）</li><li>对内脚本：短小；重要路径加注解</li><li>与 Java 交接：字段名、枚举值、错误码写成书面契约</li></ul><hr><h2 id="_2-gil-与并发现实" tabindex="-1">2. GIL 与并发现实 <a class="header-anchor" href="#_2-gil-与并发现实" aria-label="Permalink to “2. GIL 与并发现实”">​</a></h2><p>CPython 有 <strong>GIL</strong>：多线程对 CPU 密集帮助有限。</p><table tabindex="0"><thead><tr><th>场景</th><th>选择</th><th>原因</th></tr></thead><tbody><tr><td>等 HTTP / 等模型</td><td><code>asyncio</code> 或线程</td><td>多数时间在等 IO</td></tr><tr><td>CPU 密集（大文件本地重算等）</td><td>多进程、或丢给别的服务</td><td>绕过 GIL</td></tr><tr><td>真要吞吐</td><td>多实例水平扩</td><td>先扩架构</td></tr></tbody></table><p>和 Java 比：Java 真多线程共享内存更常见；Python 更适合 <strong>旁路 IO 服务</strong>，不适合硬扛所有核心域逻辑。</p><hr><h2 id="_3-asyncio-怎么用才不踩坑" tabindex="-1">3. asyncio 怎么用才不踩坑 <a class="header-anchor" href="#_3-asyncio-怎么用才不踩坑" aria-label="Permalink to “3. asyncio 怎么用才不踩坑”">​</a></h2><p><strong>适合：</strong> 同时等多个模型 API、扇出 HTTP、websocket。</p><p><strong>不适合：</strong> 在 async 函数里调用阻塞的 <code>requests</code> / 重 CPU 而不加 <code>to_thread</code>。</p><p>原则：</p><ol><li>要么整条链 async（<code>httpx.AsyncClient</code>），要么诚实用同步 + 线程池</li><li>不要「半吊子 async」：看起来并发，实际全堵在同步调用上</li><li>取消与超时：<code>asyncio.wait_for</code> / 客户端 timeout，避免任务挂死</li></ol><hr><h2 id="_4-性能边界" tabindex="-1">4. 性能边界 <a class="header-anchor" href="#_4-性能边界" aria-label="Permalink to “4. 性能边界”">​</a></h2><ul><li>默认解释执行，绝对性能通常弱于 Java/Go</li><li><strong>真瓶颈常在：</strong> 模型延迟、网络、错误重试、速率限制——不在 <code>for</code> 写得不够炫</li><li>需要吞吐：水平扩多实例，或把热点迁到 Java/Go/专用推理服务</li><li>大文件：流式处理，别一次性 <code>read()</code> 进内存</li></ul><p><strong>判断：</strong> 性能不够先看架构与下游，再怨语言。</p><hr><h2 id="_5-适合什么-不适合什么" tabindex="-1">5. 适合什么 / 不适合什么 <a class="header-anchor" href="#_5-适合什么-不适合什么" aria-label="Permalink to “5. 适合什么 / 不适合什么”">​</a></h2><table tabindex="0"><thead><tr><th>适合</th><th>不适合</th></tr></thead><tbody><tr><td>AI API 封装、批处理、运维脚本</td><td>超大单体复杂中台的第一选择</td></tr><tr><td>快速内部工具、数据清洗</td><td>强规范、强类型的超大协作域（可仍用 Java）</td></tr><tr><td>给 Java 调用的专项服务</td><td>已有稳定 Java 域还强行重写</td></tr><tr><td>Prompt / 流程验证</td><td>强事务库存核心（除非只做读写旁路）</td></tr></tbody></table><h3 id="我为什么用-python-做-ai-自动化" tabindex="-1">我为什么用 Python 做 AI / 自动化 <a class="header-anchor" href="#我为什么用-python-做-ai-自动化" aria-label="Permalink to “我为什么用 Python 做 AI / 自动化”">​</a></h3><ol><li>模型与工具 SDK 往往 Python 最全、示例最多</li><li>能快速验证 Prompt / 流程，再决定是否迁回 Java</li><li>分工清晰：<strong>Java 管业务与状态，Python 管模型与脚本</strong></li></ol><p>下一篇：<a href="./03-frameworks.html">03 框架与生态</a></p>',27)])])}const b=a(d,[["render",n]]);export{y as __pageData,b as default};
